use atlas::bfs::shortest;
use std::collections::HashMap;

fn fixture() -> HashMap<String, Vec<String>> {
    let mut links = HashMap::new();
    links.insert("alice-mac".into(), vec!["switch".into(), "app-server".into()]);
    links.insert("switch".into(), vec!["app-server".into()]);
    links
}

#[test]
fn bfs_takes_the_fewest_hop_path() {
    let links = fixture();
    assert_eq!(shortest(&links, "alice-mac", "app-server").unwrap().len(), 2);
}

